export function Notification({
  title = "{{title}}",
  message = "{{message}}",
  timeAgo = "{{timeAgo}}",
  category = "{{category}}",
  unread = {{unread}},
}) {
  const palette = { mention: { c: "#D9A3E0", icon: "@" }, system: { c: "#8A6FBF", icon: "⚙" }, message: { c: "#4E9BD9", icon: "✉" } }[category] ?? { c: "#8A6FBF", icon: "⚙" };
  return (
    <div role="status" style={{ display: "flex", alignItems: "flex-start", gap: 10, width: 300, boxSizing: "border-box",
      padding: "12px 14px", borderRadius: 10, background: unread ? "#FFFFFF" : "#FAF7F2",
      boxShadow: unread ? "0 2px 10px rgba(36,20,48,.08)" : "none", border: "1px solid #24143014",
      font: "13.5px/1.4 system-ui, sans-serif", color: "#241430" }}>
      <span aria-hidden="true" style={{ width: 26, height: 26, borderRadius: "50%", flexShrink: 0, background: palette.c,
        display: "grid", placeItems: "center", color: "#FAF7F2", fontWeight: 700, fontSize: 12 }}>{palette.icon}</span>
      <div style={{ flex: 1, minWidth: 0 }}>
        <p style={{ margin: 0, fontWeight: 700 }}>{title}</p>
        <p style={{ margin: "2px 0 0", color: "#241430b3", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{message}</p>
        <p style={{ margin: "4px 0 0", fontSize: 11, color: "#24143080" }}>{timeAgo}</p>
      </div>
      {unread && <span aria-label="Unread" style={{ width: 8, height: 8, borderRadius: "50%", background: "#B3261E", flexShrink: 0, marginTop: 4 }} />}
    </div>
  );
}
